 import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  const timelines = [];
  const primitiveControls = [];

  let meshRoot = null;

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (gltf && gltf.scene) {
        meshRoot = gltf.scene;
        meshRoot.traverse((child) => {
          if (child.isMesh) {
            child.castShadow = true;
            child.receiveShadow = true;
          }
        });
        group.add(meshRoot);
      }
    });
  }

  const primitives = config.cinematicPrimitives || [];
  for (const primitive of primitives) {
    if (ctx.primitives && ctx.primitives[primitive.name]) {
      const ctrl = ctx.primitives[primitive.name](group, primitive.params);
      if (ctrl) primitiveControls.push(ctrl);
    }
  }

  const baseY = config.position?.y ?? 0.7000000000000001;
  const hoverY = baseY + 0.15;

  group.userData.handlers = {
    hover: () => {
      const tl = gsap.to(group.position, {
        y: hoverY,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: true,
      });
      timelines.push(tl);
    },
    hoverOut: () => {
      const tl = gsap.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: true,
      });
      timelines.push(tl);
    },
    click: () => {
      const tl = gsap.timeline()
        .to(group.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'back.out(1.7)',
        })
        .to(group.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.12,
          ease: 'back.out(1.7)',
        });
      timelines.push(tl);
      ctx.emit('hub-home.select', {});
    },
    focus: () => {
      const tl = gsap.to(group.scale, {
        x: 1.02,
        y: 1.02,
        z: 1.02,
        duration: 0.3,
        ease: 'power2.out',
        yoyo: true,
        repeat: 1,
      });
      timelines.push(tl);
    },
    'trpc.visits.book.slot': (payload) => {
      group.userData.lastSlot = payload;
    },
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    primitiveControls.forEach((ctrl) => {
      if (ctrl && typeof ctrl.cleanup === 'function') ctrl.cleanup();
    });
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m?.dispose && m.dispose());
        } else if (obj.material.dispose) {
          obj.material.dispose();
        }
      }
    });
  };

  return group;
}
